'use strict';
(() => {
  const key = 'cmee-display-mode';
  const modes = ['auto', 'mobile', 'desktop'];
  const rules = [];
  for (const sheet of document.styleSheets) {
    for (const rule of sheet.cssRules) {
      if (rule.type === CSSRule.MEDIA_RULE && /^\((min|max)-width:\s*\d+px\)$/.test(rule.conditionText)) {
        rules.push({rule, query: rule.conditionText});
      }
    }
  }
  function select(mode) {
    if (!modes.includes(mode)) mode = 'auto';
    document.documentElement.dataset.layout = mode;
    // Reuse every existing responsive rule at the chosen layout width.
    const width = mode === 'mobile' ? 430 : 1280;
    for (const {rule, query} of rules) {
      const [, bound, value] = query.match(/\((min|max)-width:\s*(\d+)px\)/);
      const matches = bound === 'min' ? width >= Number(value) : width <= Number(value);
      rule.media.mediaText = mode === 'auto' ? query : matches ? 'all' : 'not all';
    }
    document.querySelectorAll('[data-layout-choice]').forEach(button => {
      button.setAttribute('aria-pressed', String(button.dataset.layoutChoice === mode));
    });
    try { localStorage.setItem(key, mode); } catch (_) {}
    document.dispatchEvent(new CustomEvent('cmee:layout', { detail: { mode } }));
  }
  document.querySelector('#layout-switch').addEventListener('click', event => {
    const button = event.target.closest('[data-layout-choice]');
    if (button) select(button.dataset.layoutChoice);
  });
  let saved = 'auto';
  try { saved = localStorage.getItem(key) || 'auto'; } catch (_) {}
  select(saved);
})();

