const pendingTable=pending.length?`<div class="table-wrap"><table><thead><tr><th>值班日期</th><th>工作时段</th><th>登记状态</th><th></th></tr></thead><tbody>${pending.slice(-5).reverse().map(s=>`<tr><td><div class="cell-main">${fmt(s.date)}</div><div class="cell-sub">${fmt(s.date,{weekday:'long'})}</div></td><td><div>${d.slots[s.slot].name}</div><div class="cell-sub">${d.slots[s.slot].start} — ${d.slots[s.slot].end}</div></td><td>${tag(s.registration_state==='draft'?'草稿待提交':'待登记','amber')}</td><td class="right"><a class="text-button" href="#register?shift=${s.id}">去登记 ${I('arrow')}</a></td></tr>`).join('')}</tbody></table></div>`:empty('登记都已完成，辛苦啦。');
