async function init(){try{S.boot=await api('bootstrap');route();if(S.boot.logged_in)await reload(false);render();if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{})}catch(e){$('#root').innerHTML=`<div class="error-page"><h1>暂时无法打开工作台</h1><p>${E(e.message)}</p>${B('重新加载','refresh')}</div>`}}

function workloadPage(){
  if(!can('can_manage_members'))return empty('仅管理员可查看成员工作统计。','shield');
  const report=S.report;if(!report)return empty('正在加载工作统计…','clock');
  const member=report.member,outside=S.params.part==='outside',f=S.reportFilters||{};
  const filter=`<form id="workload-filters" class="filters"><div class="field"><label for="hours-from">起始日期</label><input type="date" id="hours-from" name="from" value="${E(f.from||'')}"></div><div class="field"><label for="hours-to">结束日期</label><input type="date" id="hours-to" name="to" value="${E(f.to||'')}"></div><button type="submit" class="btn btn-primary">查询</button></form>`;
  let body='';
  if(!member){body=`<div class="member-work-grid">${report.summary.map(m=>`<a class="card member-work-card" href="#workload?member=${m.id}"><span class="avatar">${E(m.name.slice(-2))}</span><h2>${E(m.name)}</h2><strong>${m.regular_hours}<small> 小时</small></strong><p>正常值班 ${m.regular_count} 次</p><p>值班外记录 ${m.outside_count} 条</p><span class="text-button">查看每日事项 ${I('arrow')}</span></a>`).join('')}</div>`}
  else{
    const records=outside?report.outside:report.regular;
    body=`<div class="work-summary"><div><small>正常值班累计</small><h2>${member.regular_hours} 小时</h2><p>${member.regular_count} 个已提交班次 × 2 小时</p></div><div><small>值班时间之外</small><h2>${member.outside_count} 条记录</h2><p>只记录日期与事项，不计时长</p></div></div><section class="card"><div class="tabs"><a class="tab ${!outside?'active':''}" href="#workload?member=${member.id}&part=regular">正常值班 · ${member.regular_hours} 小时</a><a class="tab ${outside?'active':''}" href="#workload?member=${member.id}&part=outside">工作时间之外 · ${member.outside_count} 条</a></div>${records.length?records.map(r=>`<article class="work-day"><div class="row between"><strong>${E(r.date)} · ${slotLabel(r.slot)}</strong>${!outside?tag('2 小时','green'):tag('不计时长')}</div>${r.tasks.length?`<ol>${r.tasks.map(t=>`<li><span class="prewrap">${E(t.text)}</span> ${tag(t.status==='done'?'已完成':'未完成',t.status==='done'?'green':'amber')}</li>`).join('')}</ol>`:'<p class="muted">没工作 · 无具体事务</p>'}${r.notes?`<p class="prewrap">补充：${E(r.notes)}</p>`:''}<div class="row"><a class="text-button" href="#records?id=${r.id}">查看登记</a><a class="text-button" href="#register?id=${r.id}&admin=1">管理员修改</a></div></article>`).join(''):empty(outside?'没有值班外记录。':'没有已提交的正常值班登记。','records')}</section>`;
  }
  const query=new URLSearchParams({...f,state:'submitted',...(member?{author:member.id}:{})});
  return head(member?member.name+'的工作明细':'成员工作统计','仅管理员可见 · 按已提交登记统计',`${B('核对无事务 / 未登记','attendance')}${member?'<a class="btn" href="#workload">返回成员列表</a>':''}<a class="btn" href="/api/export?${E(query.toString())}">${I('download')} 导出登记表</a>`,'WORKSPACE / WORKLOAD')+`<section class="card mb">${filter}</section><p class="footnote">${I('info')} ${E(report.rule)}</p>`+body;
}
document.addEventListener('keydown',async event=>{
  const input=event.target;if(!input.matches('#task-inputs textarea')||event.key!=='Enter'||event.shiftKey||event.isComposing)return;
  event.preventDefault();const pos=input.selectionStart,end=input.selectionEnd,index=Number(input.closest('.task-input').dataset.taskIndex);
  try{if(S.saving)await S.saving;S.editor=collectEditor();if(S.editor.tasks.length>=50)throw Error('一份登记最多 50 项事务');const task=S.editor.tasks[index];if(!task)return;
    const tail=task.text.slice(end);task.text=task.text.slice(0,pos);
    if(!task.text.trim()&&!task.id){S.editor.tasks.splice(index,1);if(!S.editor.tasks.length)S.editor.work_mode='no_work'}else S.editor.tasks.splice(index+1,0,{text:tail,status:'done'});
    taskCollapsed=new Set(Array.from({length:S.editor.tasks.length},(_,k)=>k).filter(k=>k!==index+1));S.changeVersion=(S.changeVersion||0)+1;render();dirty();const next=$('#task-'+(index+1));if(next){next.focus();next.setSelectionRange(0,0)}else $('#record-notes').focus();
  }catch(e){toast(e.message,true)}
});
document.addEventListener('focusout',event=>{
  if(!event.target.matches('#task-inputs textarea'))return;
  const input=event.target;if(['打扫卫生','擦桌子','丢垃圾','倒垃圾','打扫日常卫生'].includes(input.value.trim())){input.value='日常卫生';S.changeVersion=(S.changeVersion||0)+1;dirty();toast('已统一为“日常卫生”')}
});

function recordImportPreview(p){return `<div class="mt"><h3>待新增 ${p.counts.add} 条 · 跳过重复 ${p.counts.skip} 条</h3><p>将补建 ${p.new_shifts} 个历史班次；不会触发历史催填邮件。</p>${p.errors.length?`<div class="banner warning"><div><strong>请先修正 ${p.errors.length} 项错误，再重新上传</strong><ul>${p.errors.map(e=>`<li>${E(e)}</li>`).join('')}</ul></div></div>`:''}<div class="table-wrap"><table><thead><tr><th>来源 / 人员</th><th>日期 / 时段</th><th>事务</th><th>处理</th></tr></thead><tbody>${p.changes.slice(0,100).map(r=>`<tr><td>${E(r.name)}<small class="cell-sub">${E(r.source)}</small></td><td>${E(r.date)}<br>${slotLabel(r.slot)}</td><td>${r.tasks.map((t,i)=>`${i+1}. ${E(t)}`).join('<br>')||'无具体事务'}</td><td>${r.action==='skip'?'跳过重复':'新增'}</td></tr>`).join('')}</tbody></table></div>${p.changes.length>100?'<p>预览显示前 100 条，计数涵盖整批。</p>':''}${!p.errors.length&&p.counts.add?B('确认导入这些记录','record-import-confirm','','btn-primary'):''}</div>`}
function attendanceView(d){const labels={no_work:'已登记 · 无事务（2 小时）',missing:'未登记',draft:'草稿未提交',worked:'已登记 · 有事务'};return `<p>范围：${E(S.reportFilters?.from||'最早排班')} 至 ${E(S.reportFilters?.to||'现在')}。仅核对已结束班次。</p><p>无事务 ${d.counts.no_work} 班 · 未登记 ${d.counts.missing} 班 · 草稿 ${d.counts.draft} 班 · 有事务 ${d.counts.worked} 班</p><p class="subtitle">未登记不能据此认定没有值班；没有排班的日期不计入。</p><div class="table-wrap"><table><thead><tr><th>成员</th><th>日期 / 时段</th><th>登记情况</th></tr></thead><tbody>${d.items.map(r=>`<tr><td>${E(r.name)}</td><td>${E(r.date)} · ${slotLabel(r.slot)}</td><td>${E(labels[r.status])}</td></tr>`).join('')}</tbody></table></div>${d.has_more?B('下一页','attendance-more',`data-offset="${d.next_offset}"`):''}`}

init();
const HOME_DEFAULT=['next','pending','tasks','progress','recent','notices'];
let homeDrag=null;
function stopHomeDrag(cancel=false){
  const drag=homeDrag;if(!drag)return;
  clearTimeout(drag.timer);cancelAnimationFrame(drag.frame);
  drag.ghost?.remove();drag.card.classList.remove('home-drag-origin');homeDrag=null;
  if(drag.active&&S.homeSort&&S.homeSort.owner===drag.owner){
    S.homeSort.order=cancel?drag.original:homeDOMOrder();render();
    document.querySelector(`[data-home-block="${drag.id}"] .home-drag-handle`)?.focus({preventScroll:true});
    const status=$('#home-sort-status');if(status)status.textContent=cancel?'已取消本次拖动':'顺序已调整，请点击保存顺序';
  }
}
function moveHomeDrag(drag){
  if(homeDrag!==drag||!drag.active)return;
  if(!drag.card.isConnected||S.page!=='home'){stopHomeDrag(true);return}
  drag.ghost.style.left=(drag.x-drag.dx)+'px';drag.ghost.style.top=(drag.y-drag.dy)+'px';
  const target=document.elementFromPoint(drag.x,drag.y)?.closest('#home-blocks > .home-widget');
  if(target&&target!==drag.card){
    const rect=target.getBoundingClientRect(),origin=drag.card.getBoundingClientRect();
    const sameRow=Math.abs(origin.top-rect.top)<rect.height/2;
    const after=sameRow?drag.x>rect.left+rect.width/2:drag.y>rect.top+rect.height/2;
    target.parentElement.insertBefore(drag.card,after?target.nextSibling:target);
  }
  if(drag.y<110)window.scrollBy(0,-9);
  else if(drag.y>window.innerHeight-105)window.scrollBy(0,9);
  drag.frame=requestAnimationFrame(()=>moveHomeDrag(drag));
}
document.addEventListener('pointerdown',event=>{
  const handle=event.target.closest('.home-drag-handle');
  if(!handle||!S.homeSort||homeDrag||event.button!==0)return;
  const card=handle.closest('.home-widget'),rect=card.getBoundingClientRect();
  const drag=homeDrag={card,owner:myId(),id:card.dataset.homeBlock,pointer:event.pointerId,x:event.clientX,y:event.clientY,startX:event.clientX,startY:event.clientY,dx:event.clientX-rect.left,dy:event.clientY-rect.top,original:homeDOMOrder(),active:false};
  handle.setPointerCapture(event.pointerId);
  drag.activate=()=>{
    if(homeDrag!==drag||!card.isConnected)return;
    drag.active=true;drag.ghost=document.createElement('div');drag.ghost.className='home-drag-ghost';drag.ghost.textContent=handle.textContent;
    drag.ghost.style.width=rect.width+'px';document.body.appendChild(drag.ghost);card.classList.add('home-drag-origin');
    moveHomeDrag(drag);
  };
  drag.timer=setTimeout(drag.activate,300);
});
document.addEventListener('pointermove',event=>{
  const drag=homeDrag;if(!drag||event.pointerId!==drag.pointer)return;
  drag.x=event.clientX;drag.y=event.clientY;
  if(!drag.active&&Math.hypot(drag.x-drag.startX,drag.y-drag.startY)>12){if(event.pointerType==='mouse'){clearTimeout(drag.timer);drag.activate()}else{stopHomeDrag();return}}
  if(drag.active)event.preventDefault();
},{passive:false});
document.addEventListener('pointerup',event=>{if(homeDrag?.pointer===event.pointerId)stopHomeDrag()});
document.addEventListener('pointercancel',event=>{if(homeDrag?.pointer===event.pointerId)stopHomeDrag(true)});
document.addEventListener('keydown',event=>{
  if(event.key==='Escape'&&homeDrag){stopHomeDrag(true);return}
  const handle=event.target.closest('.home-drag-handle');
  if(handle&&['ArrowUp','ArrowDown'].includes(event.key)){event.preventDefault();handle.closest('.home-widget').querySelector(`[data-step="${event.key==='ArrowUp'?-1:1}"]`)?.click()}
});


document.addEventListener('change',e=>{if(e.target.matches('#public-offer-form input[name="reply_kind"]'))publicReplyTypeChanged()});
